CREATE TABLE event71_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,kind TEXT NOT NULL,boundary TEXT NOT NULL,source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,native_id_field TEXT,native_id TEXT,raw_json TEXT NOT NULL,raw_sha256 TEXT NOT NULL,UNIQUE(run_id,source_path,pointer)) WITHOUT ROWID;
CREATE TABLE event71_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES event71_row(id),owner_field TEXT NOT NULL,owner_role_status TEXT NOT NULL,locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_main','resolved_medium','resolved_candidate_set','missing')),candidate_count INTEGER NOT NULL,selected_candidate_count INTEGER NOT NULL,UNIQUE(row_id,owner_field,locale)) WITHOUT ROWID;
CREATE TABLE event71_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES event71_slot(id),source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,tier TEXT NOT NULL CHECK(tier IN ('main','medium')),pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,raw_text_sha256 TEXT NOT NULL,selected INTEGER NOT NULL CHECK(selected IN (0,1)),UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE event71_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES event71_row(id),relation_kind TEXT NOT NULL,source_field TEXT NOT NULL,source_pointer TEXT NOT NULL,raw_locator TEXT NOT NULL,target_kind TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_unique','resolved_candidate_set','missing')),candidate_count INTEGER NOT NULL,search_complete INTEGER NOT NULL CHECK(search_complete=1),UNIQUE(row_id,relation_kind,source_pointer)) WITHOUT ROWID;
CREATE TABLE event71_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES event71_relation(id),target_row_id TEXT NOT NULL REFERENCES event71_row(id),target_source_path TEXT NOT NULL,target_source_pointer TEXT NOT NULL,target_native_id TEXT NOT NULL,UNIQUE(relation_id,target_row_id)) WITHOUT ROWID;
CREATE TABLE event71_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX event71_slot_row ON event71_slot(row_id);
CREATE INDEX event71_text_slot ON event71_text(slot_id);
CREATE INDEX event71_text_raw ON event71_text(raw_text);
CREATE INDEX event71_relation_row ON event71_relation(row_id);
CREATE INDEX event71_candidate_relation ON event71_candidate(relation_id);
CREATE TRIGGER event71_row_i BEFORE INSERT ON event71_row WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_slot_i BEFORE INSERT ON event71_slot WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_text_i BEFORE INSERT ON event71_text WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_relation_i BEFORE INSERT ON event71_relation WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_candidate_i BEFORE INSERT ON event71_candidate WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_release_i BEFORE INSERT ON event71_release WHEN EXISTS(SELECT 1 FROM event71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_row_u BEFORE UPDATE ON event71_row BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_slot_u BEFORE UPDATE ON event71_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_text_u BEFORE UPDATE ON event71_text BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_relation_u BEFORE UPDATE ON event71_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_candidate_u BEFORE UPDATE ON event71_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_release_u BEFORE UPDATE ON event71_release BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_row_d BEFORE DELETE ON event71_row BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_slot_d BEFORE DELETE ON event71_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_text_d BEFORE DELETE ON event71_text BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_relation_d BEFORE DELETE ON event71_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_candidate_d BEFORE DELETE ON event71_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
CREATE TRIGGER event71_release_d BEFORE DELETE ON event71_release BEGIN SELECT RAISE(ABORT,'immutable sealed Event 7.1');END;
